package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService defines the interface for user-related business logic
type UserService interface {
	GetAllUsers() []User
	CreateUser(u User) (User, error)
	GetUserByID(id string) (User, bool)
}

type userService struct {
	users map[string]User
	mutex sync.RWMutex
}

// NewUserService creates a new instance of UserService
func NewUserService() UserService {
	return &userService{
		users: make(map[string]User),
	}
}

func (s *userService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

func (s *userService) CreateUser(u User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.RUnlock()

	// Generate a UUID for the user ID
	u.ID = uuid.New().String()
	s.users[u.ID] = u
	return u, nil
}

func (s *userService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"rep-2/internal/service"
)

// UserHandlers handles HTTP requests for user-related operations
type UserHandlers struct {
	userService service.UserService
}

// NewUserHandlers creates a new instance of UserHandlers
func NewUserHandlers(us service.UserService) *UserHandlers {
	return &UserHandlers{userService: us}
}

// GetUsersHandler handles GET requests to /users
func (uh *UserHandlers) GetUsersHandler(w http.ResponseWriter, r *http.Request) {
	users := uh.userService.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUserHandler handles POST requests to /users
func (uh *UserHandlers) CreateUserHandler(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := uh.userService.CreateUser(u)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByIDHandler handles GET requests to /users/{id}
func (uh *UserHandlers) GetUserByIDHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	u, ok := uh.userService.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	userService := service.NewUserService()
	userHandlers := api.NewUserHandlers(userService)

	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			userHandlers.GetUsersHandler(w, r)
		case http.MethodPost:
			userHandlers.CreateUserHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			userHandlers.GetUserByIDHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"experiment/internal/api"
	"experiment/internal/service"
)

func TestUserAPI(t *testing.T) {
	userService := service.NewUserService()
	userHandlers := api.NewUserHandlers(userService)

	rr := httptest.NewRecorder()

	// Test CreateUser
	newUser := service.User{Name: "Alice", Email: "alice@example.com"}
	body, _ := json.Marshal(newUser)
	req, _ := http.NewRequest("POST", "/users", bytes.NewReader(body))

	userHandlers.CreateUserHandler(rr, req)

	if rr.Code != http.StatusCreated {
		t.Errorf("Expected status %d, got %d", http.StatusCreated, rr.Code)
	}

	var createdUser service.User
	json.NewDecoder(rr.Body).Decode(&createdUser)

	if createdUser.Name != newUser.Name || createdUser.Email != newUser.Email || createdUser.ID == "" {
		t.Errorf("Created user mismatch: %+v", createdUser)
	}

	// Test GetUsers
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest("GET", "/users", nil)

	userHandlers.GetUsersHandler(rr, req)

	if rr.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rr.Code)
	}

	var users []service.User
	json.NewDecoder(rr.Body).Decode(&users)

	if len(users) != 1 || users[0].ID != createdUser.ID {
		t.Errorf("Get all users mismatch: %+v", users)
	}

	// Test GetUserByID
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest("GET", "/users/"+createdUser.ID, nil)

	userHandlers.GetUserByIDHandler(rr, req)

	if rr.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rr.Code)
	}

	var fetchedUser service.User
	json.NewDecoder(rr.Body).Decode(&fetchedUser)

	if fetchedUser.ID != createdUser.ID {
		t.Errorf("Fetched user by ID mismatch: %+v", fetchedUser)
	}

	// Test GetUserByID (not found)
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest("GET", "/users/nonexistent", nil)

	userHandlers.GetUserByIDHandler(rr, req)

	if rr.Code != http.StatusNotFound {
		t.Errorf("Expected status %d, got %d", http.StatusNotFound, rr.Code)
	}
}
